#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# ──────────────────────────────────────────────────────────────────────────
# 阶段正文：GitHub CLI (gh) 安装向导（Windows / Git Bash）
#   • 官方页 https://cli.github.com/ ，官方推荐 winget install --id GitHub.cli
#   • 本机 hosts（生效段在第 454-483 行）把 github.com / api.github.com /
#     objects.githubusercontent.com 指向 127.0.0.1，直连下载取决于那个环回
#     加速器是否在跑 → 故保留 ghproxy 镜像 + SHA256 校验的兜底分支。
#   • 这个向导是纯动作型的：不写 .env，不设 GitHub secret / variable。
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=7

MIRROR="https://ghproxy.net/https://github.com"

# safe: 跑一条命令，吞掉 stderr，把失败变成空输出（对 set -euo pipefail 友好）。
safe() { "$@" 2>/dev/null || true; }

banner "GitHub CLI (gh) 安装向导"

# ── 1/7 ───────────────────────────────────────────────────────────────────
stage "现状检查：这台机器上有什么"

GH_BIN=""
if command -v gh >/dev/null 2>&1; then
  GH_BIN="$(command -v gh)"
elif [[ -x "/c/Program Files/GitHub CLI/gh.exe" ]]; then
  GH_BIN="/c/Program Files/GitHub CLI/gh.exe"
fi

if [[ -n "$GH_BIN" ]]; then
  say "已发现 gh：$GH_BIN"
  say "版本：$(safe "$GH_BIN" --version | head -n1)"
  note "只想升级的话：winget upgrade --id GitHub.cli --source winget"
else
  step "本机还没装 gh —— 继续，第 3 阶段会装。"
fi

GH_AUTHED=0
if [[ -n "$GH_BIN" ]] && "$GH_BIN" auth status >/dev/null 2>&1; then
  GH_AUTHED=1
  say "gh 已经是登录状态。"
fi

WINGET=""
for c in winget winget.exe; do
  if command -v "$c" >/dev/null 2>&1; then WINGET="$(command -v "$c")"; break; fi
done
if [[ -z "$WINGET" && -x "$HOME/AppData/Local/Microsoft/WindowsApps/winget.exe" ]]; then
  WINGET="$HOME/AppData/Local/Microsoft/WindowsApps/winget.exe"
fi

WINGET_OK=0
if [[ -n "$WINGET" ]]; then
  wv="$(safe "$WINGET" --version | head -n1)"
  if [[ -n "$wv" ]]; then
    WINGET_OK=1
    say "winget：$WINGET（$wv）"
  else
    warn "找到了 winget（$WINGET），但它 --version 没有输出 —— 本机 winget 目前不可用，稍后直接走 MSI。"
  fi
else
  warn "PATH 里没有 winget。"
fi

if [[ -x /c/ProgramData/chocolatey/bin/choco.exe ]]; then
  note "另有一条路：Chocolatey 在（choco install gh -y，需要管理员）。"
fi

HOSTS=/c/Windows/System32/drivers/etc/hosts
if [[ -r "$HOSTS" ]] && grep -qE '^[0-9.]+[[:space:]]+github\.com([[:space:]]|$)' "$HOSTS"; then
  warn "hosts 把 github.com 指向了 127.0.0.1：直连 GitHub 的下载要依赖本机那个加速器，它没在跑时 winget 与 github.com 的下载都会失败。"
  note "第 3 阶段为此保留了兜底：走 ghproxy 镜像下载 MSI，并用同一发布里的 checksums.txt 做 SHA256 校验。"
fi

pause "按 Enter 继续。"

# ── 2/7 ───────────────────────────────────────────────────────────────────
stage "选安装方式（打开官方页）"

say "官方在 Windows 上推荐 WinGet：winget install --id GitHub.cli --source winget"
open_url "https://cli.github.com/"
step "官方页给出各平台的安装命令；Windows 段落里就是上面那条 winget 命令。"
step "官方页打不开也不影响：本向导第 3 阶段自己就能装。"
pause "看完按 Enter。"

if [[ -n "$GH_BIN" && "$GH_AUTHED" == "1" ]]; then
  note "已经装好并登录了，安装与登录阶段默认会跳过。"
fi

METHOD="auto"
if [[ "$WINGET_OK" != "1" ]]; then
  warn "winget 在这台机器上不可用，所以本次直接走官方 MSI 安装包。"
  METHOD="msi"
elif ! confirm "先试 winget（推荐）？回答 n 就直接下载官方 MSI"; then
  METHOD="msi"
fi
say "本次安装方式：$METHOD"

# ── 3/7 ───────────────────────────────────────────────────────────────────
stage "安装 gh"

INSTALLED=0
if [[ -n "$GH_BIN" ]]; then
  say "已经装了，跳过安装。"
  INSTALLED=1
elif [[ "$METHOD" == "auto" ]]; then
  say "运行 winget install --id GitHub.cli --source winget --accept-source-agreements --accept-package-agreements"
  note "winget 自己会处理提权；弹 UAC 请允许。这里下载慢，通常是因为要走本机那个 GitHub 加速器。"
  if "$WINGET" install --id GitHub.cli --source winget --accept-source-agreements --accept-package-agreements; then
    INSTALLED=1
  else
    warn "winget 安装失败（常见原因：github.com 被指向 127.0.0.1，而加速器没在跑）。改用 MSI。"
  fi
fi

if [[ "$INSTALLED" != "1" ]]; then
  if ! command -v curl >/dev/null 2>&1; then
    warn "没有 curl，没法自动下载。请手动装："
    open_url "https://cli.github.com/"
    pause "手动装好后按 Enter 继续验证。"
  else
    say "从 ghproxy 镜像下载官方 MSI。"
    TAG=""
    effective="$(safe curl -fsSLI -o /dev/null -w '%{url_effective}' "$MIRROR/cli/cli/releases/latest")"
    TAG="$(printf '%s' "$effective" | grep -oE 'v[0-9]+\.[0-9]+\.[0-9]+' | tail -n1 || true)"
    if [[ -z "$TAG" ]]; then
      page="$(safe curl -fsSL "$MIRROR/cli/cli/releases/latest")"
      TAG="$(printf '%s' "$page" | grep -oE 'releases/tag/v[0-9]+\.[0-9]+\.[0-9]+' | head -n1 | grep -oE 'v[0-9]+\.[0-9]+\.[0-9]+' || true)"
    fi
    if [[ -z "$TAG" ]]; then
      warn "镜像没解析出最新版本号（没网，或镜像改了行为）。"
      ask GH_VERSION "手动填版本号（形如 v2.102.0；直接回车用 v2.102.0）："
      TAG="${GH_VERSION:-v2.102.0}"
    fi
    VER="${TAG#v}"
    say "版本：$TAG"

    WORK="$(mktemp -d)"
    MSI="$WORK/gh_${VER}_windows_amd64.msi"
    MSI_URL="$MIRROR/cli/cli/releases/download/$TAG/gh_${VER}_windows_amd64.msi"
    SUM_URL="$MIRROR/cli/cli/releases/download/$TAG/gh_${VER}_checksums.txt"

    say "下载：$MSI_URL"
    if safe curl -fL --retry 2 --connect-timeout 20 -o "$MSI" "$MSI_URL" && [[ -s "$MSI" ]]; then
      say "下载完成（$(safe du -h "$MSI" | cut -f1)）"
      ok=1
      if safe curl -fL --retry 2 -o "$WORK/checksums.txt" "$SUM_URL" && [[ -s "$WORK/checksums.txt" ]]; then
        want="$(grep -oE '^[0-9a-fA-F]{64}[[:space:]]+gh_'"$VER"'_windows_amd64\.msi' "$WORK/checksums.txt" | awk '{print $1}' | head -n1 || true)"
        got="$(safe sha256sum "$MSI" | awk '{print $1}')"
        if [[ -z "$want" ]]; then
          warn "checksums.txt 里没有这个文件的条目，跳过校验。"
        elif [[ "${want,,}" == "${got,,}" ]]; then
          say "SHA256 校验通过：$got"
        else
          ok=0
          warn "SHA256 不匹配！期望 $want，实际 $got"
          note "校验值取自同一个镜像，所以它只能证明传输没损坏，不能证明镜像没做手脚。"
        fi
      else
        warn "没取到 checksums.txt，跳过校验。"
      fi

      # 校验没过就要先问；用户坚持要继续也允许（但默认放弃）。
      if [[ "$ok" != "1" ]] && ! confirm "校验没通过，仍要继续安装吗？（不推荐）"; then
        warn "已放弃安装。"
        finish
        exit 1
      fi

      if command -v cygpath >/dev/null 2>&1; then MSI_WIN="$(cygpath -w "$MSI")"; else MSI_WIN="$MSI"; fi
      say "开始安装（会弹 UAC，请允许）：$MSI_WIN"
      note "msiexec 装完前请不要关这个窗口。"
      export MSI_WIN
      if powershell.exe -NoProfile -Command '$p = Start-Process msiexec.exe -ArgumentList @("/i", $env:MSI_WIN, "/qb") -Verb RunAs -Wait -PassThru; exit $p.ExitCode'; then
        say "安装器已结束。"
      else
        warn "安装器返回非零或没启动起来。可以手动双击安装：$MSI_WIN"
      fi
    else
      warn "下载失败：镜像不通或者没网。"
      open_url "https://cli.github.com/"
      pause "手动装好后按 Enter 继续验证。"
    fi
  fi
fi

# ── 4/7 ───────────────────────────────────────────────────────────────────
stage "验证 gh --version"

export PATH="$PATH:/c/Program Files/GitHub CLI"
if command -v gh >/dev/null 2>&1; then
  say "gh 位置：$(command -v gh)"
  say "版本信息："
  safe gh --version | sed 's/^/    /'
else
  warn "当前窗口里还找不到 gh。"
  note "刚装完的话，把 Git Bash 关掉重开再跑一次；MSI 默认装到 C:\\Program Files\\GitHub CLI。"
  note "如果那个目录里也没有 gh.exe，说明第 3 阶段没装成功。"
fi

pause "看到版本号就按 Enter 继续（没看到也继续，后面还能补救）。"

# ── 5/7 ───────────────────────────────────────────────────────────────────
stage "登录 GitHub（gh auth login）"

if [[ "$GH_AUTHED" == "1" ]] && ! confirm "gh 已经是登录状态，要重新登录吗？"; then
  say "保持当前登录，跳过。"
else
  say "先打开设备授权页备用（登录时要用）："
  open_url "https://github.com/login/device"
  step "gh 会依次问：GitHub.com → HTTPS → 是否用 gh 管理 git 凭据（Yes）→ Login with a web browser"
  step "它会给一个一次性代码（形如 XXXX-XXXX），并用 --clipboard 复制到剪贴板"
  step "浏览器里粘贴代码、点 Authorize 即可"
  warn "本机 github.com / api.github.com 指向 127.0.0.1：登录能否成功取决于那个加速器是否在跑。失败就先启动加速器，再重跑本向导。"
  pause "按 Enter 开始登录（Ctrl-C 可中断）。"
  if gh auth login --hostname github.com --git-protocol https --web --clipboard; then
    say "登录流程结束。"
  else
    warn "gh auth login 返回非零。备选：gh auth login --web，或在提示里选 Paste an authentication token。"
  fi
fi

# ── 6/7 ───────────────────────────────────────────────────────────────────
stage "让 git 用 gh 的凭据（gh auth setup-git）"

if command -v gh >/dev/null 2>&1; then
  if gh auth setup-git; then
    say "已写入 git 的凭据配置（~/.gitconfig 里的 credential helper）。"
  else
    warn "gh auth setup-git 没成功；如果上一阶段没登录成功，先回去完成登录。"
  fi
  note "注意：你的仓库 origin 走的是 ghproxy 镜像（https://ghproxy.net/https://github.com/sganggs/Stronghold-Protocol.git），这步对它不生效 —— push 仍按镜像自己的规则来。"
  say "当前登录状态："
  safe gh auth status | sed 's/^/    /'
else
  warn "还没找到 gh，跳过。"
fi

pause "按 Enter 继续。"

# ── 7/7 ───────────────────────────────────────────────────────────────────
stage "收尾核对"

if command -v gh >/dev/null 2>&1; then
  say "gh：$(safe gh --version | head -n1)"
else
  SKIPPED+=("把 gh 装好（第 3 阶段没成功，或需要新开一个终端再确认）")
fi
if command -v gh >/dev/null 2>&1 && ! gh auth status >/dev/null 2>&1; then
  SKIPPED+=("完成 gh auth login（这次没登录成功）")
fi

note "新开的 cmd / PowerShell / Git Bash 窗口里才有 gh；本向导只是临时把 C:\\Program Files\\GitHub CLI 加进了 PATH。"
note "常用命令：gh auth status · gh repo view · gh pr create · gh issue list · gh workflow run"
note "这个向导没有改动仓库里的任何文件：不写 .env，也不设 GitHub secret / variable。"

finish
